CREATE INDEX "memory_relations_lexical_idx" ON "memory"."relations" USING gin ((lower(normalize("relation_type" || ' ' || "context"::text || ' ' || "payload"::text, NFKC))) gin_trgm_ops) WHERE "memory"."relations"."deleted_at" IS NULL;--> statement-breakpoint
CREATE INDEX "record_versions_lexical_idx" ON "dataset"."record_versions" USING gin ((lower(normalize(coalesce("context_snapshot"->>'title','') || ' ' || coalesce("plain_text",'') || ' ' || "content"::text, NFKC))) gin_trgm_ops) WHERE "dataset"."record_versions"."is_current" AND "dataset"."record_versions"."deleted_at" IS NULL;